// Scripted negotiation rules stay separate from model-generated speech.
export const offers = [
 {id:'scope',actor:'sales',title:'缩小交付范围',line:'客户其实只需要知识库检索。我可以争取先验收这一项，但你要在第 3 轮前做出可用版本。',promise:'第 3 轮前产品进度达到 55%',due:3,metric:'product',threshold:55,up:{trust:10},win:{cash:24,trust:8},lose:{trust:-22},success:'首期验收通过，客户支付 24 万。',failure:'承诺的首期产品没有完成，客户撤回了采购意向。'},
 {id:'team',actor:'cto',title:'承诺保护研发时间',line:'我收到了另一家公司的邀请。如果你能在第 2 轮前让产品达到 40%，我就留下。别再把研发时间拿去做路演。',promise:'第 2 轮前产品进度达到 40%',due:2,metric:'product',threshold:40,up:{morale:5},win:{morale:12,product:8},lose:{morale:-25,product:-10},success:'陈默拒绝了外部邀请，带团队完成了技术补强。',failure:'研发承诺落空，陈默退出核心交付，产品进度回退。'},
 {id:'bridge',actor:'investor',title:'用控制权换过桥资金',line:'我可以现在给你 36 万。但第 4 轮前必须把客户信任做到 65，否则董事会接管经营。你愿意签吗？',promise:'第 4 轮前客户信任达到 65%',due:4,metric:'trust',threshold:65,up:{cash:36},win:{morale:4},lose:{morale:-15},success:'融资对赌达标，你保住了经营权。',failure:'融资对赌未达标：公司获得了现金，但董事会接管经营。'}
];
function emit(w,e){w.events.push({id:w.events.length+1,round:w.round,visibility:'public',...e});}
function change(w,effects){const changes={};for(const [k,v] of Object.entries(effects)){const m=w.scenario.metrics.find(x=>x.id===k);const before=w.metrics[k];w.metrics[k]=Math.max(m.min,Math.min(m.max,before+v));changes[k]=w.metrics[k]-before;}return changes;}
export function initStory(w){if(w.scenario.id!=='startup'||!['ceo','cto','sales','investor'].every(id=>w.actors.some(a=>a.id===id)))return;if(!['cash','product','trust','morale'].every(k=>Number.isFinite(w.metrics[k])))return;w.story={deals:[],heard:[],controlLost:false,alert:'今晚必须决定：先稳住团队，还是先拿到钱？'};for(const o of offers)emit(w,{type:'message',actorId:o.actor,target:'ceo',visibility:'private',title:w.actors.find(a=>a.id===o.actor).name,text:o.line});}
export function talk(w,id){if(!w.story||w.result)throw new Error('当前世界无法谈判');const o=offers.find(x=>x.id===id);if(!o)throw new Error('未知谈判');if(w.story.heard.includes(id))return;o && w.story.heard.push(id);emit(w,{type:'message',actorId:o.actor,target:'ceo',visibility:'private',title:w.actors.find(a=>a.id===o.actor).name,text:o.line});}
export function accept(w,id){if(!w.story||w.result)throw new Error('当前世界无法交易');const o=offers.find(x=>x.id===id);if(!o||w.round>=o.due||w.story.deals.some(d=>d.id===id))throw new Error('这项交易已结束或已接受');w.story.deals.push({id,status:'pending',acceptedAt:w.round});emit(w,{type:'deal',title:'签下承诺 · '+o.title,text:o.promise+'。到期按实际状态结算。',changes:change(w,o.up)});}
export function settleStory(w){if(!w.story)return;w.story.alert=null;for(const d of w.story.deals){const o=offers.find(o=>o.id===d.id);if(d.status!=='pending'||w.round<o.due)continue;const ok=w.metrics[o.metric]>=o.threshold;d.status=ok?'fulfilled':'broken';d.settledAt=w.round;if(d.id==='scope'&&ok&&!w.completed.includes('sell'))w.completed.push('sell');if(d.id==='bridge'&&!ok)w.story.controlLost=true;emit(w,{type:'promise',title:ok?'承诺兑现':'承诺落空',text:ok?o.success:o.failure,changes:change(w,ok?o.win:o.lose)});w.story.alert=ok?o.success:o.failure;}
 if(w.round===1){w.story.alert='客户要求明确交付范围。尚未签下的交易仍可谈判，但期限不会延后。';emit(w,{type:'message',actorId:'sales',target:'ceo',visibility:'private',title:'许知夏',text:'客户刚追问演示日期。我们只剩一个窗口缩小范围，你现在要给我一个答复。'});}
 if(w.round===3&&!w.story.deals.some(d=>d.id==='team')){const text='陈默没有等到留任承诺，决定减少在公司的投入。';emit(w,{type:'crisis',title:'技术负责人缩减投入',text,changes:change(w,{product:-8,morale:-12})});w.story.alert=text;}
}
export function finishStory(w){if(!w.story||!w.result)return;for(const d of w.story.deals)if(d.status==='pending')d.status='unresolved';const broken=w.story.deals.filter(d=>d.status==='broken').length;w.result.text+=w.story.controlLost?' 董事会接管了经营，你失去了控制权。':' 你仍保有经营权。';w.result.text+=` ${broken} 项承诺落空。`;}
